{
	cfg := newConfig(newBinderConfig())

	baseLogger, level, undo := logging.Zap()
	defer undo()
	log := baseLogger.Sugar()
	if err := level.UnmarshalText([]byte(cfg.logLevel())); err != nil {
		log.Error(err)
		return nil, err
	}

	rdmclient := setUpRdmClient(cfg)

	apiAuthenticator, err := NewAuthenticator(cfg)
	if err != nil {
		log.Error(err)
		return nil, err
	}

	publisher, err := newKafkaPublisher(cfg, baseLogger)
	if err != nil {
		log.Error(err)
		return nil, err
	}

	partnerPublisher := messaging.NewPartnerPublisher(cfg.RetailFeedTopic, publisher, log)

	api := restapi.New(apiAuthenticator, rdmclient, partnerPublisher, log)

	log.Info("All configurations successfully configured")

	return &App{
		api:    api,
		logger: log,
	}, nil
}

