	transport := innerRoundTripper
	if innerRoundTripper == nil {
		transport = http.DefaultTransport
	}

	for i := len(customRoundTrippers) - 1; i >= 0; i-- {
		roundTripper := customRoundTrippers[i]
		transport = roundTripper(transport)
	}

	return transport
}

