func (a *API) receivePartnerNotification(ctx context.Context, w http.ResponseWriter, r *http.Request) error {
	a.logger.Info("Partner Notification Received from RDM")
	w.Header().Set("Content-Type", "application/json")

	switch r.Method {
	case "POST":

		body, err := io.ReadAll(r.Body)
		if err != nil {
			a.logger.Error("Cannot process request ", err.Error())

			w.WriteHeader(http.StatusBadRequest)
			if _, err := w.Write([]byte(`{"message": "Bad Request"}`)); err != nil {
				a.logger.Error(err)
			}
			return err
		}

		modifiedRequest := "{\"partnerNotifications\":" + string(body) + "}"

		var partnerNotifications pb.PartnerNotifications

		// Convert received json request to notification structure
		err = json.Unmarshal([]byte(modifiedRequest), &partnerNotifications)

		if err != nil {
			a.logger.Error("Cannot process request ", err.Error())

			w.WriteHeader(http.StatusBadRequest)
			if _, err := w.Write([]byte(`{"message": "Bad Request"}`)); err != nil {
				a.logger.Error(err)
			}
			return err
		}

		for _, partnerNotification := range partnerNotifications.GetPartnerNotifications() {
			if partnerNotification.GetData().GetValidationUrl() != "" && partnerNotification.GetData().GetValidationCode() != "" {
				type Response struct {
					ValidationResponse string `json:"validationResponse"`
				}

				a.logger.Info("Received validation details, returning with code : ", partnerNotification.GetData().GetValidationCode())
				w.WriteHeader(http.StatusOK)

				res := Response{
					ValidationResponse: partnerNotification.GetData().GetValidationCode(),
				}

				if err := json.NewEncoder(w).Encode(res); err != nil {
					a.logger.Error(err)
				}

				return nil
			}

			partnerID := partnerNotification.GetData().GetPartnerId()
			partner, err := a.rdmClient.GetPartnerData(ctx, partnerID)
			if err != nil {
				a.logger.Error(err)
				return err
			}

			err = a.eventWriter.PublishPartners(ctx, []domain.Partner{partner})
			if err != nil {
				a.logger.Error(err)
				return err
			}
		}

	default:
		w.WriteHeader(http.StatusNotFound)
		if _, err := w.Write([]byte(`{"message": "Service not found"}`)); err != nil {
			a.logger.Error(err)
		}
		return nil
	}
	w.WriteHeader(http.StatusOK)
	if _, err := w.Write([]byte(`{"message": "Received Details"}`)); err != nil {
		a.logger.Error(err)
	}
	return nil
}

