		) {
			return a.publicKey, nil
		})
	if err != nil {
		return VTSClaims{}, fmt.Errorf("parsing token: %w", err)
	}

	claims, _ := token.Claims.(*VTSClaims)

	if !token.Valid {
		return VTSClaims{}, errors.New("invalid token")
	}

	if claims.Issuer != a.issuer {
		return VTSClaims{}, errors.New("token not issued for volvocars")
	}

	if claims.Audience != a.domain {
		return VTSClaims{}, errors.New("token has the wrong audience")
	}

	if err := claims.Valid(); err != nil {
		return VTSClaims{}, fmt.Errorf("token unavailable: %w", err)
	}

	trlReq, err := http.Get(a.trlURL + a.domain)
	if err != nil {
		return nil, err
	}

	defer trlReq.Body.Close()

	trlBody, err := io.ReadAll(trlReq.Body)
	if err != nil {
		return nil, err
	}

	trl := &TRL{}
	if err := json.Unmarshal(trlBody, trl); err != nil {
		return nil, fmt.Errorf("failed to unmarshal: %w", err)
	}

	for _, revoked := range trl.RevokedTokens {
		if claims.Vti == revoked {
			return VTSClaims{}, errors.New("token is on the revocation list")
		}
	}

	return claims, nil
}

